mapper.delete:
delete from cr_title_user
where title_id in
#{title_id}

mapper.select:
select T1.*, T2.name as level, count(T3.id) as trains_count from cr_title T1 left join cr_title_level T2 on T1.level_id = T2.resource_id left join cr_title_business_template T3 on T1.resource_id = T3.title_id
T1.`name` like #{name}
group by T1.resource_id order by T1.id desc

select T1.title_id as resource_id, T2.level_id, T2.create_user_id, T2.name as name, T3.name as level from cr_title_user T1 left join cr_title T2 on T1.title_id = T2.resource_id left join cr_title_level T3 on T2.level_id = T3.resource_id
T1.user_id = #{user_id}
and T2.level_id = #{level_id}
and T2.name = #{title}
order by T1.create_time desc

select T1.resource_id, T1.name as train_name, T1.business_type, count(T2.id) as train_count, ifnull(max(score), 0) as max_score from cr_business_template T1 left join cr_title_train_progress T2 on T1.resource_id = T2.business_template_id and T2.user_id = #{user_id}
T1.resource_id in (select business_template_id from cr_title_business_template where title_id = #{title_id})
group by T1.resource_id order by T2.create_time desc

select T5.name as title_name, T5.resource_id as title_id, T1.name as train_name, T2.user_id as create_user, T1.resource_id, T1.business_type, count(T2.id) as train_count, ifnull(max(score), 0) as max_score from cr_business_template T1 left join cr_title_train_progress T2 on T1.resource_id = T2.business_template_id left join (select T3.resource_id,T3.name,T4.business_template_id,T3.level_id from cr_title T3 left join cr_title_business_template T4 on T3.resource_id = T4.title_id left join cr_title_level T6 on T3.level_id = T6.resource_id) T5 on T5.business_template_id = T1.resource_id
1= 1 and T1.resource_id in (select business_template_id from cr_title_business_template)
and T5.name = #{title}
and T5.level_id = #{level_id}
and T2.user_id in
#{user_id}
group by T5.resource_id,T1.resource_id,T2.user_id

select T1.resource_id, T1.name, T1.create_user_id, T1.score, T2.resource_id as level_id, T2.name as level from cr_title T1 left join cr_title_level T2 on T1.level_id = T2.resource_id
1 = 1
and T1.level_id = #{level_id}
and T1.name = #{title}

select distinct `name` from cr_title where resource_id in (
    select title_id from cr_title_business_template where business_template_id = #{business_template_id}
)
